import numpy as np

C = 343.0  # m/s

def gcc_phat(sig, ref, fs, max_tau=None, interp=16):
    """Generalized cross-correlation with phase transform weighting."""
    n = sig.shape[0] + ref.shape[0]
    R = np.fft.rfft(sig, n=n) * np.conj(np.fft.rfft(ref, n=n))
    cc = np.fft.irfft(R / (np.abs(R) + 1e-12), n=interp * n)
    max_shift = int(interp * n / 2) if max_tau is None else min(int(interp * fs * max_tau), int(interp * n / 2))
    cc = np.concatenate((cc[-max_shift:], cc[:max_shift + 1]))
    return (np.argmax(np.abs(cc)) - max_shift) / float(interp * fs)

def tau_to_angle(tau, d=0.058):
    # 마이크 간 시간지연(TDOA)으로 음원 입사각 계산, d=마이크 간격(m)
    return np.degrees(np.arcsin(np.clip(tau * C / d, -1, 1)))

